#!/usr/bin/env node

/**
 * Script to generate og-image.png from pwa-icon-108.png
 * Requires: sharp (npm install sharp)
 * 
 * Usage: node scripts/generate-og-image.mjs
 * 
 * OG image is generated by placing pwa-icon-108.png (scaled to 400x400) 
 * centered on a 1200x630px amber background.
 */

import sharp from 'sharp';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const rootDir = join(__dirname, '..');

async function generateOGImage() {
  try {
    const sourcePath = join(rootDir, 'public', 'pwa-icon-108.png');
    const outputPath = join(rootDir, 'public', 'og-image.png');
    
    // Create OG image with icon centered on gradient background
    await sharp({
      create: {
        width: 1200,
        height: 630,
        channels: 3,
        background: { r: 254, g: 243, b: 199 } // Amber-50 background
      }
    })
    .composite([
      {
        input: await sharp(sourcePath)
          .resize(400, 400, { fit: 'contain' })
          .toBuffer(),
        left: 400,
        top: 115
      }
    ])
    .png()
    .toFile(outputPath);
    
    console.log(`✓ Generated ${outputPath} from pwa-icon-108.png`);
  } catch (error) {
    console.error('Error generating OG image:', error.message);
    console.log('\nNote: Install sharp first: npm install sharp');
    process.exit(1);
  }
}

generateOGImage();
